'use strict';
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const paths={back:'<path d="m15 4-8 8 8 8"/>',more:'<circle cx="4" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="20" cy="12" r="1"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',play:'<path d="M7 3v18l15-9Z"/>',pause:'<path d="M6 3h4v18H6zM14 3h4v18h-4z"/>',heart:'<path d="M12 21S1 14 1 7a6 6 0 0 1 11-3A6 6 0 0 1 23 7c0 7-11 14-11 14Z"/>',flag:'<path d="M5 22V3c5-5 8 5 15 0v11c-7 5-10-5-15 0"/>',folder:'<path d="M2 6h8l2 2h10v12H2ZM2 6V3h8l2 3h8v2"/>',server:'<path d="m5 3-3 12h20L19 3ZM2 15v5h20v-5M6 18h1"/>',settings:'<path d="m9 2-1 3-3 1-2 4 2 2-1 4 3 2 3-1 3 3 3-2 1-3 3-1v-4l-3-1-1-4-4-1Z"/><circle cx="11" cy="11" r="3"/>',library:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m10 8 6 4-6 4Z"/>',wifi:'<path d="M2 7c6-5 14-5 20 0M6 11c4-3 8-3 12 0M10 15c1-1 3-1 4 0"/><circle cx="12" cy="19" r="1"/>',cast:'<rect x="2" y="2" width="20" height="16" rx="3"/><path d="m7 23 5-7 5 7"/>',unlock:'<rect x="2" y="10" width="18" height="12" rx="3"/><path d="M9 10V5c0-6 10-6 10 0M9 16h4"/>',lock:'<rect x="2" y="10" width="18" height="12" rx="3"/><path d="M6 10V5c0-6 10-6 10 0v5M9 16h4"/>',rotate:'<rect x="2" y="2" width="11" height="20" rx="3"/><path d="M17 3c5 2 5 6 4 8m-3-1 3 1 2-3M17 14h5v8h-5"/>',image:'<rect x="2" y="3" width="20" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 19 6-6 3 3 4-6 5 8"/>',pip:'<rect x="1" y="2" width="20" height="16" rx="2"/><rect x="12" y="12" width="11" height="10" rx="1" fill="currentColor"/><path d="m4 5 5 5m0-4v4H5"/>',list:'<rect x="1" y="2" width="22" height="20" rx="3"/><path d="m5 6 4 3-4 3ZM12 8h7M5 15h14M5 18h10"/>',prev:'<path d="M3 4h2v16H3zM20 4 7 12l13 8Z"/>',next:'<path d="M19 4h2v16h-2zM4 4l13 8-13 8Z"/>',rewind:'<path d="m11 4-11 8 11 8Zm12 0-11 8 11 8Z"/>',forward:'<path d="m1 4 11 8L1 20Zm12 0 11 8-11 8Z"/>',subtitle:'<rect x="1" y="3" width="22" height="18" rx="3"/><path d="M5 12h5m3 0h6M5 16h11m2 0h1"/>',expand:'<rect x="1" y="2" width="22" height="20" rx="3"/><path d="M5 9V6h3m11 9v3h-3"/>',video:'<path d="M1 5h14v15H1zm14 4 8-4v15l-8-4Z"/>',music:'<path d="M10 2v15c-9-4-11 8-3 6 4-1 4-4 4-7V7l12-3V0Z"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.more}</svg>`;
const btn=(label,action,ico,cls='')=>`<button class="${cls}" aria-label="${label}" data-action="${action}">${icon(ico)}</button>`;
const img=(asset,alt='',cls='')=>`<img src="assets/${asset}.jpg" alt="${alt}" class="${cls}" draggable="false">`;
const state={playTitle:'后会友期',route:'home',returnTo:'series',favorite:{},flagged:{},episode:5,range:0,playing:true,seconds:15,duration:4790,speed:1,subtitle:'关闭',audio:'AAC stereo · 默认',hero:0,locked:false};
const movieRows=[['动漫',[['ling','灵笼行者','2026 - 现在','6.0'],['nian','一念永恒','2020 - 现在','8.4'],['xian','仙逆','2023 - 现在','8.3'],['cang','沧元图','2023 - 现在','8.5']]],['其他视频',[['food','食贫道充电纪录','2023 - 现在','']]],['视频库-电视剧',[['rose','玫瑰战争','2026 - 现在','8.0'],['rain','谷雨','2026 - 现在','9.0'],['princess','尚公主','2026 - 现在','8.0'],['war','我的有趣时代','2026 - 现在','8.2']]],['视频库-电影',[['film','仙逆剧场版：弑仙之战','2026','7.5'],['house','最后访屋','2026','6.9'],['night','一夜限定','2026','6.6'],['spider','蜘蛛侠：新纪元','2026','8.0']]],['综艺',[['show1','后会友期','2026 - 现在','8.0'],['show2','街头世界斗士','2026 - 现在','9.0'],['show3','大哥小助理','2026 - 现在','9.0']]]];
const poster=(v,route='film')=>`<button class="poster-card" data-route="${v[0]==='princess'?'series':route}" aria-label="查看${v[1]}"><div class="poster-art">${img(v[0],v[1])}</div><div class="card-title">${v[1]}</div><div class="card-sub">${v[2]}</div></button>`;
function status(time='11:48'){return `<div class="statusbar"><span>${time}</span><span class="status-right">3.93 KB/s ▴ 5G ▴ 5G ${icon('wifi')}<b class="battery">100</b></span></div>`;}
function heading(text,action=''){return `<h2 class="section-heading"><span>${text}</span>${action?`<button data-action="${action}">查看全部 ›</button>`:''}</h2>`;}
function home(){return `<div class="screen home">${status()}<div class="topbar"><button class="profile" data-action="profile"><span>${icon('play')}</span><span>wines</span></button><div class="topbar-right">${btn('搜索','search','search','circle')}${btn('更多','home-more','more','circle')}</div></div><section class="hero-home">${img('home-hero','魅影神捕海报','hero-art')}<div class="hero-meta"><span class="star">★</span> 8.0 | 2026 | 剧情</div><div class="dots">${Array.from({length:9},(_,i)=>`<button class="${i===state.hero?'active':''}" data-hero="${i}" aria-label="轮播第${i+1}张"></button>`).join('')}</div></section><section class="section first">${heading('继续观看')}<div class="rail">${[['continue-xian','仙逆','S1:E159 - 仙迹'],['continue-awake','觉醒年代','S1:E3 - 陈独秀创办青年杂志']].map((v,i)=>`<button class="wide-card" data-route="player"><div class="wide-image">${img(v[0],v[1])}</div><div class="card-title">${v[1]}</div><div class="card-sub">${v[2]}</div></button>`).join('')}</div></section><section class="section">${heading('我的媒体')}<div class="rail">${[['library-anime','动漫'],['library-other','其他视频']].map(v=>`<button class="wide-card" data-action="library-${v[1]}"><div class="wide-image">${img(v[0],v[1])}</div><div class="card-title">${v[1]}</div></button>`).join('')}</div></section>${movieRows.map((r,i)=>`<section class="section">${heading(r[0],'all-'+i)}<div class="rail">${r[1].map(v=>poster(v,i===2?'series':'film')).join('')}</div></section>`).join('')}<nav class="bottom-nav" aria-label="主导航">${[['library','媒体库','home'],['folder','文件库','files'],['server','影视服务器','servers'],['settings','设置','settings']].map((x,i)=>`<button data-action="${x[2]}" class="${i===0?'active':''}">${icon(x[0])}${x[1]}</button>`).join('')}</nav></div>`;}
const filmPeople=[['石头熊','导演'],['史泽鲲','Wang Lin<br>(voice)'],['李嘉祥','Li Yuan 李元<br>(voice)'],['刘思岑','Xu Li Guo 许立国 (voice)'],['关帅','Xue Zu 血祖']];
const seriesPeople=[['孟子义','Mu Wanyao'],['李昀锐','Yan Shang'],['吴汉坤','Yang Si'],['李孝谦','Feng Shu'],['Yu Ailei','Yu Cheng']];
function people(series){return `<section class="section">${heading('演职人员')}<div class="rail people">${(series?seriesPeople:filmPeople).map((p,i)=>`<button class="person" data-person="${p[0]}">${img(`${series?'series':'film'}-person-${i}`,p[0])}<div class="person-name">${p[0]}</div><div class="person-role">${p[1]}</div></button>`).join('')}</div></section>`;}
function episodes(){let start=[1,11,21,33][state.range],end=[10,20,32,40][state.range];return `<section class="section episodes"><h2 class="section-heading"><button data-action="season" style="font-size:16px">第 1 季⌄</button><button data-action="episodes">查看全部 ›</button></h2><div class="rail">${Array.from({length:end-start+1},(_,i)=>i+start).map(n=>`<button class="episode-card ${n===state.episode?'selected':''}" data-episode="${n}"><div class="episode-image">${n===1?img('episode','第一集'):n}</div><div class="card-title">${n} ${n===1?'顶好嗑不烧心！孟子义李昀锐':n===2?'我要怎么感谢你呢？慕晚瑶':'尚公主 · 第 '+n+' 集'}</div></button>`).join('')}</div><div class="range-tabs">${['1-10','11-20','21-32','33-40'].map((v,i)=>`<button class="${i===state.range?'active':''}" data-range="${i}">${v}</button>`).join('')}</div></section>`;}
function detail(series=false){let key=series?'series':'film';return `<div class="screen detail ${key}">${status(series?'11:50':'11:48')}<div class="topbar">${btn('返回媒体库','back','back')}${btn('影片更多操作','detail-more','more')}</div><section class="detail-hero">${img(key+'-hero',series?'尚公主海报':'仙逆剧场版：弑仙之战海报')}</section><div class="detail-meta">${series?'<span class="star">★</span> 8.0 | 2026/10/23 | Tencent Video | 剧情 | <span style="border:1px solid #fff9;border-radius:3px">SG-NC16</span><div class="technical">共1季</div>':'<span class="star">★</span> 7.5 | 2026/10/1 | 动画,动作,冒险,奇幻<div class="technical">1小时32分钟 · 5.13 GB · 4K HEVC</div>'}</div><button class="play-button" data-action="play">${icon('play')}播放</button><div class="detail-actions">${btn('收藏影片','favorite','heart',state.favorite[key]?'selected':'')}${btn('标记已看','flag','flag',state.flagged[key]?'selected':'')}</div><div class="purple-rating"><span>✓</span>${series?'9.4':'8.5'}</div>${series?episodes():''}${people(series)}<section class="section">${heading('类型')}<div class="genres">${(series?['剧情']:['动画','动作','冒险','奇幻']).map(v=>`<button class="genre" data-genre="${v}">${v}</button>`).join('')}</div></section><section class="section related">${heading('相关影片')}<div class="rail">${(series?[['蒸蒸日上','2026','7.8'],['花开锦绣','2026','7.6'],['漫长的季节','2023','8.8'],['传闻中的陈芊芊','2020','7.3']]:[['仙逆剧场版：弑仙之战','2025','6.7'],['天空之城','1986','8.0'],['哪吒闹海','1979','7.7'],['大闹天宫','1961','9.0']]).map((v,i)=>poster([key+'-related-'+i,...v],key)).join('')}</div></section>${series?'':mediaInfo()}<div class="home-indicator"></div></div>`;}
function mediaInfo(){return `<section class="section">${heading('音视频字幕信息')}<div class="rail"><article class="media-info"><h3>${icon('video')}视频</h3>${['标题: 4K HEVC','编码: hevc','配置文件: Main','等级: 150','分辨率: 3840x1598','宽高比: 1920:799','隔行扫描: 否','帧率: 25.000','比特率: 7837 kbps','视频范围: SDR','基色: bt709','色域: bt709','色偏: bt709','位深度: 8 bit','像素格式: yuv420p','参考帧: 1'].map(s=>`<p>${s}</p>`).join('')}</article><article class="media-info"><h3>${icon('music')}音频</h3>${['标题: AAC stereo','编码: aac','声道布局: stereo','声道数: 2 ch','采样率: 48000 Hz','配置文件: LC','隔行扫描: 否','比特率: 125 kbps','默认: 是'].map(s=>`<p>${s}</p>`).join('')}</article><article class="media-info"><h3>${icon('subtitle')}字幕</h3><p>标题: 简体中文</p><p>格式: 演示轨道</p><p>默认: 关闭</p></article></div></section><div class="file-info">demo/media/仙逆剧场版：弑仙之战 (2026).mkv<br>1小时32分钟 5.13 GB 4K HEVC</div>`;}
function fmt(v){let n=Math.floor(v),h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=n%60;return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function speedLabel(){return (Number.isInteger(state.speed)?state.speed.toFixed(1):String(state.speed))+'x';}
function playbackTitle(){return state.playTitle==='仙逆剧场版：弑仙之战'?state.playTitle:state.playTitle+' 第1季 第'+state.episode+'集';}
function player(){return `<div class="player ${state.playing?'':'is-paused'} ${state.locked?'locked':''}"><div class="video-picture" data-action="toggle-controls"></div><div class="player-controls"><div class="player-status"><span>${icon('wifi')}6.4 MB/s</span><span>下午11:51 ▰</span></div><div class="player-top">${btn('退出播放','exit-player','back')}<strong>${playbackTitle()}</strong><span class="spacer"></span>${btn('投屏','cast','cast')}${btn('播放器选项','player-more','more')}</div><div class="side-controls left">${btn('锁定屏幕','lock','unlock')}${btn('旋转屏幕','rotate','rotate','rotate-control')}</div><div class="side-controls right">${btn('截图','snapshot','image')}${btn('画中画','pip','pip')}</div><div class="timeline"><span id="elapsed">${fmt(state.seconds)}</span><input aria-label="播放进度" type="range" min="0" max="${state.duration}" value="${state.seconds}" id="seek"><span>${fmt(state.duration)}</span></div><div class="player-bottom">${btn('播放列表','episodes','list')}<div class="transport">${btn('上一集','prev','prev')}${btn('快退10秒','rewind','rewind')}${btn(state.playing?'暂停':'播放','toggle-play',state.playing?'pause':'play','toggle-play')}${btn('快进10秒','forward','forward')}${btn('下一集','next','next')}</div><div class="right-bottom"><button data-action="speed" aria-label="播放速度">${speedLabel()}</button>${btn('字幕与音轨','tracks','subtitle')}${btn('画面比例','aspect','expand')}</div></div></div>${btn('解锁屏幕','unlock','lock','unlock-only')}</div><p class="player-hint">本地交互模拟 · 视频画面为截图无控件区域裁剪，非真实播放。空格暂停，方向键快进 / 快退。</p>`;}
function render(){state.route=location.hash.slice(1)||'home';if(!['home','film','series','player'].includes(state.route))state.route='home';document.body.classList.toggle('player-mode',state.route==='player');app.innerHTML=state.route==='home'?home():state.route==='player'?player():detail(state.route==='series');document.querySelectorAll('.study-shell nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+state.route));document.title=`VidHub · ${ {home:'媒体库',film:'电影详情',series:'剧集详情',player:'播放器'}[state.route]}`;}
function route(to){closeModal();location.hash=to;window.scrollTo(0,0);if(state.route===to)render();}
function toast(s){let e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2400);}
function modal(title,body){modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-header"><h2>${title}</h2>${btn('关闭弹层','close-modal','close')}</div>${body}</section></div>`;modalRoot.querySelector('input,button')?.focus();}
function closeModal(){modalRoot.innerHTML='';}
function options(title,items,action,selected=''){modal(title,items.map(s=>`<button class="option ${s===selected?'selected':''}" data-choice="${action}" data-value="${s}">${s}${s===selected?' ✓':''}</button>`).join(''));}
function showEpisodes(){modal('第 1 季 · 选集',`<div class="modal-grid">${Array.from({length:40},(_,i)=>`<button class="${state.episode===i+1?'selected':''}" data-episode="${i+1}">${i+1}</button>`).join('')}</div>`);}
function refreshPlayer(){if(state.route==='player')app.innerHTML=player();}
function changeSeek(value){state.seconds=Math.max(0,Math.min(state.duration,value));document.querySelector('#elapsed')?.replaceChildren(document.createTextNode(fmt(state.seconds)));let seek=document.querySelector('#seek');if(seek)seek.value=state.seconds;}
function action(a){if(a.startsWith('research-'))return researchAction(a);switch(a){case'home':route('home');break;case'back':route('home');break;case'play':state.returnTo=state.route;state.playTitle=state.route==='film'?'仙逆剧场版：弑仙之战':'尚公主';route('player');break;case'exit-player':route(state.returnTo);break;case'favorite':state.favorite[state.route]=!state.favorite[state.route];render();toast(state.favorite[state.route]?'已添加到收藏':'已取消收藏');break;case'flag':state.flagged[state.route]=!state.flagged[state.route];render();toast(state.flagged[state.route]?'已标记为看过':'已取消已看标记');break;case'close-modal':closeModal();break;case'episodes':showEpisodes();break;case'season':options('选择季',['第 1 季'],'season','第 1 季');break;case'toggle-play':state.playing=!state.playing;refreshPlayer();break;case'rewind':changeSeek(state.seconds-10);break;case'forward':changeSeek(state.seconds+10);break;case'prev':state.episode=Math.max(1,state.episode-1);state.seconds=0;refreshPlayer();break;case'next':state.episode=Math.min(40,state.episode+1);state.seconds=0;refreshPlayer();break;case'speed':options('播放速度',['0.5x','0.75x','1.0x','1.25x','1.5x','2.0x'],'speed',speedLabel());break;case'tracks':modal('字幕与音轨',`<h3 style="font-size:13px;font-weight:400;color:#aaa">字幕</h3>${['关闭','简体中文','繁體中文','English'].map(v=>`<button class="option ${v===state.subtitle?'selected':''}" data-choice="subtitle" data-value="${v}">${v}${v===state.subtitle?' ✓':''}</button>`).join('')}<h3 style="font-size:13px;font-weight:400;color:#aaa">音轨</h3>${['AAC stereo · 默认','原声 · 立体声'].map(v=>`<button class="option ${v===state.audio?'selected':''}" data-choice="audio" data-value="${v}">${v}${v===state.audio?' ✓':''}</button>`).join('')}`);break;case'lock':state.locked=true;refreshPlayer();break;case'unlock':state.locked=false;refreshPlayer();break;case'toggle-controls':document.querySelector('.player')?.classList.toggle('hide-controls');break;case'cast':modal('投屏',`<p>以下为演示设备，不会连接真实电视。</p><button class="option" data-choice="cast" data-value="客厅电视">▣ 客厅电视 <span style="float:right;color:#aaa">演示</span></button><button class="option" data-choice="cast" data-value="卧室电视">▣ 卧室电视 <span style="float:right;color:#aaa">演示</span></button>`);break;case'aspect':options('画面比例',['适应屏幕','填充屏幕','16:9','原始比例'],'aspect','适应屏幕');break;case'rotate':document.body.classList.toggle('clean');break;case'pip':modal('画中画',`<p>这是截图交互原型，没有可送入系统画中画的视频流。</p><button class="option" data-action="close-modal">返回播放器</button>`);break;case'snapshot':toast('已模拟截图 · 当前没有真实视频流');break;case'search':modal('搜索影片','<input id="search-input" placeholder="搜索电影、电视剧、动漫" aria-label="搜索影片"><div id="search-results"></div>');search('');break;case'profile':options('wines',['当前资料库','切换演示资料库'],'profile','当前资料库');break;case'home-more':options('媒体库',['刷新媒体库','显示全部分类','排序方式'],'home-more');break;case'detail-more':options('影片选项',['添加到收藏','标记已看','查看媒体信息'],'detail-more');break;case'player-more':options('播放选项',['播放速度','字幕与音轨','画面比例','线路管理','网络与缓存','播放设置','退出播放'],'player-more');break;case'files':modal('文件库','<button class="option" data-route="film">▱ 电影 / 仙逆剧场版：弑仙之战.mkv</button><button class="option" data-route="series">▱ 电视剧 / 尚公主</button><p>演示目录，不包含真实媒体文件。</p>');break;case'servers':modal('影视服务器','<button class="option" data-choice="server" data-value="家庭媒体库">▣ 家庭媒体库 <span style="float:right">演示</span></button><p>界面原型不读取或保存服务器地址、账号和密钥。</p>');break;case'settings':settingsHub();break;default:if(a.startsWith('all-')){let r=movieRows[+a.slice(4)];modal(r[0],`<div class="rail" style="flex-wrap:wrap;padding:0">${r[1].map(v=>poster(v)).join('')}</div>`);}else if(a.startsWith('library-')){action(a==='library-动漫'?'all-0':'all-1');}}}
function choice(type,val){closeModal();if(type.startsWith('research-'))return researchChoice(type,val);if(type==='speed'){state.speed=parseFloat(val);refreshPlayer();}else if(type==='subtitle'){state.subtitle=val;toast('字幕：'+val);}else if(type==='audio'){state.audio=val;toast('音轨：'+val);}else if(type==='cast'){toast(val+' · 已模拟选择');}else if(type==='aspect'){let p=document.querySelector('.video-picture');if(p){p.style.left=val==='填充屏幕'?'0':'10%';p.style.right=val==='填充屏幕'?'0':'10%';}toast('画面比例：'+val);}else if(type==='detail-more'){action({'添加到收藏':'favorite','标记已看':'flag'}[val]||'media-info');if(val==='查看媒体信息'){if(state.route==='series')modal('媒体信息','<p>共1季 · 40集 · 演示剧集数据</p>');else document.querySelector('.media-info')?.scrollIntoView({behavior:'smooth'});}}else if(type==='player-more'){action({'播放速度':'speed','字幕与音轨':'tracks','画面比例':'aspect','线路管理':'research-network','网络与缓存':'research-cache','播放设置':'research-playback','退出播放':'exit-player'}[val]);}else if(type==='home-more'){if(val==='显示全部分类')document.querySelectorAll('.section')[2]?.scrollIntoView({behavior:'smooth'});else if(val==='排序方式')options('排序方式',['默认顺序','名称','年份'],'sort','默认顺序');else toast('演示媒体库已刷新');}else if(type==='settings'){modal(val,'<p>此功能展示截图对应的界面方向。原型所有交互和播放均为本地模拟，不构成实际 VidHub 行为或性能证据。</p>');}else toast(val);}
function search(q){const all=movieRows.flatMap(x=>x[1]).filter(v=>v[1].includes(q));let target=document.querySelector('#search-results');if(target)target.innerHTML=all.length?all.map(v=>`<button class="option" data-route="${v[0]==='princess'?'series':'film'}">${v[1]} <small style="color:#aaa">${v[2]}</small></button>`).join(''):'<p>没有匹配的影片</p>';}
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))return closeModal();let b=e.target.closest('button,[data-route]');if(!b)return;if(b.dataset.route){if(b.dataset.route==='player'){state.returnTo='home';state.playTitle=b.querySelector('.card-title')?.textContent||'后会友期';}route(b.dataset.route);}else if(b.dataset.action)action(b.dataset.action);else if(b.dataset.choice)choice(b.dataset.choice,b.dataset.value);else if(b.dataset.episode){state.episode=+b.dataset.episode;state.seconds=0;closeModal();if(state.route==='player')refreshPlayer();else{state.returnTo='series';state.playTitle='尚公主';route('player');}}else if(b.dataset.range){state.range=+b.dataset.range;let section=document.querySelector('.episodes');if(section)section.outerHTML=episodes();}else if(b.dataset.hero){state.hero=+b.dataset.hero;document.querySelectorAll('.dots button').forEach((x,i)=>x.classList.toggle('active',i===state.hero));let art=document.querySelector('.hero-home .hero-art');art.src=`assets/${['home-hero','film-hero','series-hero'][state.hero%3]}.jpg`;art.alt=['魅影神捕海报','仙逆海报','尚公主海报'][state.hero%3];}else if(b.dataset.person)modal(b.dataset.person,'<p>演员资料页 · 本地演示</p><button class="option" data-route="series">查看参演剧集</button>');else if(b.dataset.genre)modal(b.dataset.genre,`<div class="rail" style="padding:0">${movieRows[0][1].map(v=>poster(v)).join('')}</div>`);});
document.addEventListener('input',e=>{if(e.target.id==='seek')changeSeek(+e.target.value);if(e.target.id==='search-input')search(e.target.value.trim());});
document.addEventListener('keydown',e=>{if(e.target.matches('input'))return;if(e.key==='Escape'){if(modalRoot.innerHTML)closeModal();else if(state.route==='player')route(state.returnTo);else route('home');}if(state.route==='player'&&!state.locked&&!modalRoot.innerHTML){if(e.code==='Space'){e.preventDefault();action('toggle-play');}if(e.key==='ArrowRight')action('forward');if(e.key==='ArrowLeft')action('rewind');}});
document.querySelector('#clean-view').onclick=()=>document.body.classList.add('clean');document.querySelector('#exit-clean').onclick=()=>document.body.classList.remove('clean');if(new URLSearchParams(location.search).has('clean'))document.body.classList.add('clean');
if(new URLSearchParams(location.search).get('still')==='1')document.body.classList.add('capture');
window.addEventListener('hashchange',render);render();
setInterval(()=>{if(state.route==='player'&&state.playing&&!state.locked&&new URLSearchParams(location.search).get('still')!=='1')changeSeek(Math.min(state.duration,state.seconds+state.speed));},1000);


