const researchState={routeMode:null,routes:[],nextRouteId:1,selectedRoute:null,playback:{},cache:{}};
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const studyNotice='<p class="research-notice"><strong>研究推演 · 交互模拟</strong><br>本页没有实机截图参照。资源名称有静态证据，布局为研究补充；设置只保存在当前页面，不改变原应用。</p>';
function evidenceNote(body){return `<details class="source-note"><summary>查看依据与限制</summary>${body}</details>`;}
function settingsHub(){modal('设置',`${studyNotice}<button class="option" data-action="research-network">线路管理 <span class="setting-value">›</span></button><button class="option" data-action="research-cache">网络与缓存 <span class="setting-value">›</span></button><button class="option" data-action="research-playback">播放设置 <span class="setting-value">›</span></button><button class="option" data-action="research-reset">重置本次模拟</button>`);}
function networkPanel(){let s=researchState;modal('线路管理',`${studyNotice}<div class="research-caption">线路选择 · ${s.routeMode==='auto'?'自动选择最快线路':s.routeMode==='manual'?'手动选择':'未设置（原应用默认未知）'}</div><button class="option ${s.routeMode==='auto'?'selected':''}" data-choice="research-route-mode" data-value="auto">自动选择最快线路 ${s.routeMode==='auto'?'✓':''}</button><button class="option ${s.routeMode==='manual'?'selected':''}" data-choice="research-route-mode" data-value="manual">切换线路 · 手动 ${s.routeMode==='manual'?'✓':''}</button><div class="research-caption">线路列表 · 本地演示数据</div><button class="option ${s.selectedRoute===0?'selected':''}" data-choice="research-route-select" data-value="0">主线路 <span class="setting-value">${s.selectedRoute===0?'已选择':'未连接'}</span></button>${s.routes.map(r=>`<div class="route-row"><button class="option ${s.selectedRoute===r.id?'selected':''}" data-choice="research-route-select" data-value="${r.id}">${escapeText(r.name)}<small>${escapeText(r.server)||'未填写地址'}${r.port?':'+escapeText(r.port):''}</small></button><button aria-label="编辑${escapeText(r.name)}" data-choice="research-route-edit" data-value="${r.id}">编辑</button></div>`).join('')}<button class="option" data-action="research-route-add">＋ 添加备份线路</button><button class="option" data-action="research-route-refresh">刷新线路</button><p class="research-caption">没有执行线路探测、测速、请求或切换服务器。</p>${evidenceNote('<p>ReArk 线路资源：media_server_routes_title、media_server_route_auto_fastest、media_server_route_primary、media_server_route_switch、add_backup_route_title、edit_backup_route_title、media_server_routes_refresh。</p><p>证据：01-network-route.txt:6–18。只能证明相应资源存在；自动最快探测算法、回退和默认选择未知。</p>')}<button class="option" data-action="research-settings">‹ 返回设置</button>`);}
function routeForm(id=null){let r=researchState.routes.find(x=>x.id===id)||{name:'',server:'',port:''};modal(id===null?'添加备份线路':'编辑备份线路',`${studyNotice}<form id="research-route-form" data-route-id="${id===null?'':id}" novalidate><label class="research-field">名称<input name="name" aria-label="线路名称" value="${escapeText(r.name)}" autocomplete="off"></label><label class="research-field">服务器地址<input name="server" aria-label="服务器地址" value="${escapeText(r.server)}" placeholder="仅演示，不连接" autocomplete="off" spellcheck="false"></label><label class="research-field">端口<input name="port" aria-label="端口" inputmode="numeric" value="${escapeText(r.port)}" placeholder="1–65535" autocomplete="off"></label><div id="route-form-error" class="form-error" role="alert"></div><button class="research-save" type="submit">保存本次模拟</button></form>${id===null?'':`<button class="option" data-choice="research-route-delete" data-value="${id}">删除此线路</button>`}${evidenceNote('<p>backup_route_input_name / server / port，toast_backup_route_name_required = Name is required.；toast_backup_route_port_invalid = Enter a valid port from 1 to 65535.</p><p>显示中文为研究译文，原文见上；服务器地址必填与否未知，不增加该校验。保存按钮及流程为原型推演。</p>')}<button class="option" data-action="research-network">‹ 返回线路管理</button>`);}
function placeholderResearchPanel(kind){modal(kind==='cache'?'网络与缓存':'播放设置',`${studyNotice}<p>相关资源正在核实。未证实的容量、缓冲时长、播放内核或硬件解码默认值不作预设。</p><button class="option" data-action="research-settings">‹ 返回设置</button>`);}
function researchAction(a){if(a==='research-settings')settingsHub();else if(a==='research-network')networkPanel();else if(a==='research-route-add')routeForm();else if(a==='research-route-refresh'){networkPanel();toast('已刷新本地演示列表 · 未执行网络请求');}else if(a==='research-cache')evidenceSettingsPanel('cache');else if(a==='research-playback')evidenceSettingsPanel('playback');else if(a==='research-reset'){researchState.routeMode=null;researchState.routes=[];researchState.selectedRoute=null;researchState.playback={};researchState.cache={};settingsHub();toast('已重置本次设置模拟');}}
function researchChoice(type,val){if(type==='research-setting-open'){const [group,key]=val.split(':');openResearchSetting(group,key);return;}if(type==='research-setting-value'){saveResearchSetting(val);return;}if(type==='research-route-mode'){researchState.routeMode=val;networkPanel();}else if(type==='research-route-select'){researchState.selectedRoute=Number(val);researchState.routeMode='manual';networkPanel();toast('已选择演示线路 · 未连接');}else if(type==='research-route-edit')routeForm(Number(val));else if(type==='research-route-delete'){modal('删除此线路？',`<p>仅删除本页的演示线路。</p><button class="option" data-choice="research-route-delete-confirm" data-value="${Number(val)}">删除</button><button class="option" data-choice="research-route-edit" data-value="${Number(val)}">取消</button>`);}else if(type==='research-route-delete-confirm'){researchState.routes=researchState.routes.filter(r=>r.id!==Number(val));if(researchState.selectedRoute===Number(val))researchState.selectedRoute=null;networkPanel();}}
document.addEventListener('submit',e=>{if(e.target.id!=='research-route-form')return;e.preventDefault();let f=e.target,d=new FormData(f),name=String(d.get('name')).trim(),server=String(d.get('server')).trim(),port=String(d.get('port')).trim(),err=document.querySelector('#route-form-error');if(!name){err.textContent='名称不能为空。Name is required.';return;}if(!/^\d+$/.test(port)||Number(port)<1||Number(port)>65535){err.textContent='请输入 1–65535 的有效端口。Enter a valid port from 1 to 65535.';return;}let id=f.dataset.routeId?Number(f.dataset.routeId):researchState.nextRouteId++,route={id,name,server,port:String(Number(port))},index=researchState.routes.findIndex(r=>r.id===id);if(index<0)researchState.routes.push(route);else researchState.routes[index]=route;networkPanel();toast('演示线路已保存 · 未执行连接');});


