function evidenceSettingsPanel(group){let defs=group==='cache'?cacheSettings:playbackSettings,values=researchState[group];modal(group==='cache'?'网络与缓存':'播放设置',`${studyNotice}<p class="research-caption">所有初始值均未设置；原应用运行时默认值尚未验证。</p>${defs.map(d=>`<button class="option research-setting-row" data-choice="research-setting-open" data-value="${group}:${d.key}"><span>${d.label}</span><span class="setting-value">${escapeText(researchSettingLabel(values[d.key]))} ›</span></button>`).join('')}${group==='cache'?'<p class="research-caption">资源说明：磁盘缓存会占用空间；大小或时长满足条件后停止缓存。另有建议在高码率或网络不稳定时使用的文案。这不证明当前模拟已缓存或达到性能收益。</p>':''}${evidenceNote(`<p>来源：02-cache-playback-resources.txt:6–26，ReArk query_resource_table("settings_playback")。</p><p>${defs.map(d=>`${d.source} = ${d.english}`).join('<br>')}</p>${group==='cache'?'<p>settings_playback_cache_size_default_value = 512 MB 是资源字符串，不等于已确认的运行时默认。时长格式 %1$d min；大小格式 %1$d MB / %1$s GB。未取得档位映射或时长候选数组。</p>':'<p>网盘候选资源：settings_playback_resolution_high = Play highest resolution video stream；settings_playback_resolution_orignal = Play original video file。</p><p>开关的“开启/关闭”是模拟状态表达，不证明系统能力、当前偏好或实际硬解路径。播放内核选择未证实，本面板未添加内核切换。</p>'}`)}<button class="option" data-action="research-settings">‹ 返回设置</button>`);}
function openResearchSetting(group,key){let d=(group==='cache'?cacheSettings:playbackSettings).find(x=>x.key===key);if(!d)return;if(d.numeric)return numericResearchSetting(key);let current=researchState[group][key];modal(d.label,`${studyNotice}${d.note?`<p class="research-risk">${d.note}</p>`:''}${['未设置',...(d.values||['开启','关闭'])].map(v=>`<button class="option ${researchSettingLabel(current)===v?'selected':''}" data-choice="research-setting-value" data-value="${group}:${key}:${v}">${v}${researchSettingLabel(current)===v?' ✓':''}</button>`).join('')}<p class="research-caption">${d.values?'上述两个播放选项的名称有资源证据。':'开启/关闭仅用于演示本页选中态，不执行设备功能。'}</p>${evidenceNote(`<p>${d.source} = ${d.english}</p><p>实际默认、调用路径、支持设备与生效条件未知。</p>`)}<button class="option" data-action="research-${group==='cache'?'cache':'playback'}">‹ 返回${group==='cache'?'网络与缓存':'播放设置'}</button>`);}
function numericResearchSetting(key){let value=researchState.cache[key],parts=value?value.split(' '):[],unit=key==='duration'?'分钟':parts[1]||'MB';modal(key==='size'?'缓存大小':'缓存时长',`${studyNotice}<p class="research-caption">候选档位和上下限未取得。输入任意正数仅演示数值编辑，不代表原应用允许范围；留空表示未设置。</p><form id="research-number-form" data-setting-key="${key}" novalidate><label class="research-field">${key==='size'?'容量':'时长'}<input name="amount" aria-label="${key==='size'?'缓存大小数值':'缓存时长数值'}" type="text" inputmode="decimal" value="${escapeText(parts[0]||'')}" placeholder="未设置" autocomplete="off"></label>${key==='size'?`<label class="research-field">单位<select name="unit" aria-label="缓存大小单位"><option value="MB" ${unit==='MB'?'selected':''}>MB</option><option value="GB" ${unit==='GB'?'selected':''}>GB</option></select></label>`:'<p class="research-caption">单位：分钟（资源格式 %1$d min）</p>'}<div id="research-number-error" class="form-error" role="alert"></div><button type="submit" class="research-save">保存本次模拟</button></form>${evidenceNote(key==='size'?'<p>资源：settings_playback_cache_size、settings_playback_cache_size_mib_format、settings_playback_cache_size_gib_format。512 MB仅为默认文案资源，不作本页初始值。</p>':'<p>资源：settings_playback_cache_duration，settings_playback_cache_duration_format = %1$d min。原应用时长档位未证实。</p>')}<button class="option" data-action="research-cache">‹ 返回网络与缓存</button>`);}
function saveResearchSetting(encoded){let [group,key,val]=encoded.split(':');if(!['playback','cache'].includes(group))return;let defs=group==='cache'?cacheSettings:playbackSettings,d=defs.find(x=>x.key===key);if(!d)return;if(val==='未设置')delete researchState[group][key];else if((d.values||['开启','关闭']).includes(val))researchState[group][key]=val;evidenceSettingsPanel(group);}
document.addEventListener('submit',e=>{if(e.target.id!=='research-number-form')return;e.preventDefault();let f=e.target,key=f.dataset.settingKey,data=new FormData(f),raw=String(data.get('amount')).trim(),value=Number(raw);if(raw===''){delete researchState.cache[key];evidenceSettingsPanel('cache');return;}let valid=/^\d+(?:\.\d+)?$/.test(raw)&&Number.isFinite(value)&&value>0&&(key!=='duration'||Number.isSafeInteger(value));if(!valid){document.querySelector('#research-number-error').textContent=key==='duration'?'演示输入需为正整数分钟，或留空取消设置。':'演示输入需为有限正数，或留空取消设置。';return;}researchState.cache[key]=`${value} ${key==='duration'?'分钟':data.get('unit')==='GB'?'GB':'MB'}`;evidenceSettingsPanel('cache');toast('已保存演示值 · 未写入真实播放器');});
